ALTER TABLE blog_posts
  ADD COLUMN featured_image_alt VARCHAR(255) NULL AFTER featured_image,
  ADD COLUMN meta_title VARCHAR(220) NULL AFTER published_at,
  ADD COLUMN meta_description VARCHAR(320) NULL AFTER meta_title,
  ADD COLUMN focus_keyword VARCHAR(120) NULL AFTER meta_description,
  ADD COLUMN author_name VARCHAR(120) NOT NULL DEFAULT 'Yayın Editörü' AFTER focus_keyword,
  ADD COLUMN reading_time TINYINT UNSIGNED NOT NULL DEFAULT 5 AFTER author_name,
  ADD COLUMN is_featured TINYINT(1) NOT NULL DEFAULT 0 AFTER reading_time,
  ADD COLUMN views_count BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER is_featured;

CREATE TABLE IF NOT EXISTS blog_categories (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(120) NOT NULL,
 slug VARCHAR(140) NOT NULL UNIQUE,
 description VARCHAR(500) NULL,
 sort_order INT NOT NULL DEFAULT 0,
 is_active TINYINT(1) NOT NULL DEFAULT 1,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_tags (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 name VARCHAR(100) NOT NULL,
 slug VARCHAR(120) NOT NULL UNIQUE,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_post_category (
 post_id BIGINT UNSIGNED NOT NULL,
 category_id BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(post_id,category_id),
 CONSTRAINT fk_blog_pc_post FOREIGN KEY(post_id) REFERENCES blog_posts(id) ON DELETE CASCADE,
 CONSTRAINT fk_blog_pc_category FOREIGN KEY(category_id) REFERENCES blog_categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_post_tag (
 post_id BIGINT UNSIGNED NOT NULL,
 tag_id BIGINT UNSIGNED NOT NULL,
 PRIMARY KEY(post_id,tag_id),
 CONSTRAINT fk_blog_pt_post FOREIGN KEY(post_id) REFERENCES blog_posts(id) ON DELETE CASCADE,
 CONSTRAINT fk_blog_pt_tag FOREIGN KEY(tag_id) REFERENCES blog_tags(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

