INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Kaş’ta Villa Tatili: Bilmeniz Gereken 8 Şey','kasta-villa-tatili-rehberi','Kaş’ın koylarını, mahallelerini ve villa seçeneklerini keşfederken tatilinizi daha konforlu planlamanın yolları.','<p>Kaş, berrak denizi, taş sokakları ve sakin atmosferiyle Akdeniz’in en özel tatil duraklarından biridir. Burada villa tatili planlarken yalnızca manzaraya değil, günlük ihtiyaçlarınıza ve ulaşım tercihlerinize de dikkat etmek gerekir.</p><h2>Konum seçimini doğru yapın</h2><p>Merkeze yakın konaklamalar restoran ve limana yürüyüş kolaylığı sunarken, yamaçlardaki villalar daha geniş manzara ve mahremiyet sağlayabilir. Kendi aracınız yoksa market ve plaj mesafesini mutlaka kontrol edin.</p><h2>Havuz ve manzara detaylarını inceleyin</h2><p>Özel havuzun korunaklı olup olmadığını, güneş alma saatlerini ve deniz manzarasının hangi odalardan görüldüğünü sorun. Fotoğrafların güncel olmasına dikkat edin.</p><h2>Tatilinizi önceden planlayın</h2><p>Yüksek sezonda popüler tarihler hızlı dolabilir. İptal koşullarını okuyun, giriş-çıkış saatlerini teyit edin ve çevredeki koylar için birkaç alternatif rota hazırlayın.</p><p>Kaş’ta iyi bir villa tatili, doğru konum ve beklentilerinize uygun konaklamayı seçmekle başlar.</p>','https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=1200&q=85','Kaş bölgesinde havuzlu villa ve Akdeniz manzarası','published',DATE_SUB(NOW(),INTERVAL 1 DAY),'Kaş Villa Tatili Rehberi: 8 Önemli İpucu','Kaş’ta villa seçimi, konum, özel havuz ve tatil planlaması için pratik öneriler.','Kaş villa tatili','VillaStay Editör','6',1
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='kasta-villa-tatili-rehberi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Kalkan’da Deniz Manzaralı Villa Seçmenin Püf Noktaları','kalkanda-deniz-manzarali-villa-secimi','Kalkan’ın yamaçlarına yayılan manzaralı villalar arasından size en uygun olanı nasıl seçebilirsiniz?','<p>Kalkan, teraslarından Akdeniz’e açılan manzarası ve özel havuzlu konaklama seçenekleriyle öne çıkar. Ancak manzara kadar villanın konumu, ulaşım ve günlük kullanım kolaylığı da önemlidir.</p><h2>Manzara yönünü sorun</h2><p>Fotoğraflarda görülen manzaranın yatak odalarından mı, salondan mı yoksa yalnızca terastan mı izlendiğini öğrenin. Gün batımı ve güneş alma yönü tatil deneyimini etkileyebilir.</p><h2>Yokuş ve ulaşım</h2><p>Kalkan’ın eğimli coğrafyasında araç ihtiyacını değerlendirin. Merkeze yürüme mesafesi yazsa bile dönüş yolunun yokuşlu olabileceğini unutmayın.</p><h2>Havuz mahremiyeti</h2><p>Havuz alanının çevre yapılardan görünürlüğünü, korunaklılık seviyesini ve çocuk güvenliği önlemlerini kontrol edin.</p><p>İlan detaylarını dikkatle karşılaştırmak, Kalkan’da beklentinize uygun bir konaklama bulmanızı kolaylaştırır.</p>','https://images.unsplash.com/photo-1613490493576-7fde63acd811?auto=format&fit=crop&w=1200&q=85','Deniz manzaralı modern villa havuzu','published',DATE_SUB(NOW(),INTERVAL 3 DAY),'Kalkan Deniz Manzaralı Villa Seçimi | Villa Rehberi','Kalkan’da manzaralı villa seçerken konum, ulaşım, havuz mahremiyeti ve manzara detayları.','Kalkan deniz manzaralı villa','VillaStay Editör','5',1
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='kalkanda-deniz-manzarali-villa-secimi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Fethiye’de Ailece Yapılabilecek 7 Güzel Aktivite','fethiyede-ailece-yapilacak-aktiviteler','Fethiye tatilinde çocuklarla ve tüm aileyle keyifli zaman geçirebileceğiniz duraklar.','<p>Fethiye, doğa ve denizi bir araya getiren rotaları sayesinde aile tatilleri için pek çok seçenek sunar. Günlerinizi yalnızca plajda geçirmek yerine farklı deneyimler ekleyebilirsiniz.</p><h2>Ölüdeniz ve sakin koylar</h2><p>Deniz koşullarını ve çocukların yaşını dikkate alarak uygun plajları seçin. Gölgelik, tuvalet ve yeme içme imkânlarını önceden araştırın.</p><h2>Tekne turu ve doğa yürüyüşleri</h2><p>Hava durumuna uygun, ailelere elverişli kısa tekne turlarını değerlendirin. Serin saatlerde kolay parkurlarda yürüyüş yapabilirsiniz.</p><h2>Kayaköy ve yerel pazarlar</h2><p>Kültür gezileri, yerel ürünleri tanıma ve küçük keşifler çocukların tatiline çeşitlilik katar.</p><p>Programınızı esnek tutun ve her gün için dinlenme zamanı bırakın.</p>','https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=85','Fethiye kıyısında turkuaz deniz','published',DATE_SUB(NOW(),INTERVAL 5 DAY),'Fethiye Aile Aktiviteleri: 7 Öneri','Fethiye’de çocuklarla plaj, tekne turu, doğa ve kültür gezileri için aile rehberi.','Fethiye aile aktiviteleri','VillaStay Editör','5',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='fethiyede-ailece-yapilacak-aktiviteler');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Özel Havuzlu Villa mı, Ortak Havuzlu Tatil Köyü mü?','ozel-havuzlu-villa-mi-tatil-koyu-mu','Mahremiyet, bütçe ve hizmet beklentilerine göre iki konaklama modelini karşılaştırın.','<p>Tatil konaklaması seçerken özel havuzlu villa ile ortak havuzlu tesis arasında kalabilirsiniz. İki seçeneğin de farklı avantajları vardır.</p><h2>Özel havuzlu villanın avantajları</h2><p>Kendi alanınızda vakit geçirmek, esnek saatler ve daha fazla mahremiyet isteyenler için uygundur. Aile ve arkadaş gruplarında ortak yaşam alanı avantaj sağlar.</p><h2>Ortak havuzlu tesisin avantajları</h2><p>Resepsiyon, restoran, günlük temizlik ve sosyal alanlar gibi hizmetler arayanlar için daha pratik olabilir.</p><h2>Karar verirken</h2><p>Toplam fiyatı, temizlik ücretlerini, ulaşımı, yemek imkânlarını ve iptal koşullarını birlikte değerlendirin. Kişi başı maliyeti hesaplamak karşılaştırmayı kolaylaştırır.</p>','https://images.unsplash.com/photo-1572331165267-854da2b10ccc?auto=format&fit=crop&w=1200&q=85','Özel havuzlu villa terası','published',DATE_SUB(NOW(),INTERVAL 7 DAY),'Özel Havuzlu Villa mı Tatil Köyü mü? Karşılaştırma','Özel havuzlu villa ve ortak havuzlu tesisleri mahremiyet, hizmet ve maliyet açısından karşılaştırın.','özel havuzlu villa','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='ozel-havuzlu-villa-mi-tatil-koyu-mu');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Balayı İçin Villa Seçerken Romantik Detaylar','balayi-icin-romantik-villa-secimi','İki kişilik tatilinizi unutulmaz kılacak manzara, havuz ve konum detayları.','<p>Balayı tatilinde konaklama, birlikte geçireceğiniz zamanın atmosferini belirler. Romantik bir villa seçerken görsellerin ötesindeki ayrıntıları da inceleyin.</p><h2>Size özel alan</h2><p>Korunaklı havuz, özel teras ve rahat bir oturma alanı çiftler için keyifli bir ortam sunabilir.</p><h2>Manzara ve konum</h2><p>Gün batımı manzarası, sessiz bir çevre veya sahile yakınlık gibi önceliklerinizi belirleyin. Restoranlara ulaşım ve transfer ihtiyacını hesaba katın.</p><h2>Küçük dokunuşlar</h2><p>Jakuzi, şömine, geniş yatak odası veya özel yemek alanı gibi özellikleri gerçekten kullanıp kullanmayacağınızı düşünün.</p><p>Balayı için en iyi villa, sizin ortak beklentilerinizi karşılayan ve rahat hissettiren seçenektir.</p>','https://images.unsplash.com/photo-1582719508461-905c673771fd?auto=format&fit=crop&w=1200&q=85','Romantik balayı konaklaması ve özel havuz','published',DATE_SUB(NOW(),INTERVAL 9 DAY),'Balayı Villası Seçimi: Romantik Tatil Rehberi','Balayı için özel havuz, manzara, mahremiyet ve konum açısından villa seçme önerileri.','balayı villası','VillaStay Editör','4',1
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='balayi-icin-romantik-villa-secimi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Villa Tatilinde Bavula Neler Koymalı?','villa-tatilinde-bavul-listesi','Villa konaklamasında ihtiyaç duyabileceğiniz eşyaları pratik bir kontrol listesiyle hazırlayın.','<p>Villa tatili için bavul hazırlarken otel konaklamasından farklı ihtiyaçlarınız olabilir. Önce konaklama yerinde sunulan ekipmanları öğrenin ve gereksiz eşya taşımayın.</p><h2>Günlük ihtiyaçlar</h2><p>Kişisel bakım ürünleri, güneş kremi, şapka, güneş gözlüğü, rahat ayakkabı ve plaj çantası temel ihtiyaçlar arasındadır.</p><h2>Çocuklu aileler için</h2><p>Çocukların sevdiği atıştırmalıklar, güneş koruyucu, yedek mayo ve ihtiyaç duydukları özel ürünleri ekleyin.</p><h2>Elektronik ve belgeler</h2><p>Şarj cihazları, powerbank, kimlik ve rezervasyon bilgilerinizi kolay ulaşabileceğiniz yerde tutun.</p><p>Havlu, saç kurutma makinesi, mutfak ekipmanı ve nevresim gibi ürünlerin dahil olup olmadığını ev sahibinden teyit edin.</p>','https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85','Seyahat bavulu ve hazırlık eşyaları','published',DATE_SUB(NOW(),INTERVAL 11 DAY),'Villa Tatili Bavul Listesi: Unutulmaması Gerekenler','Villa tatili öncesi kişisel bakım, plaj, çocuk ve elektronik ihtiyaçları için bavul listesi.','villa tatili bavul listesi','VillaStay Editör','3',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='villa-tatilinde-bavul-listesi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Erken Rezervasyonla Villa Tatilini Planlamanın Avantajları','erken-rezervasyon-villa-tatili','Tarih ve villa seçeneği konusunda daha fazla esneklik için erken planlama önerileri.','<p>Villa tatili için erken rezervasyon, özellikle okul tatilleri ve yaz sezonu gibi yoğun dönemlerde daha geniş seçenekleri değerlendirme fırsatı sunabilir.</p><h2>Daha fazla seçenek</h2><p>Erken planlama yaptığınızda kişi kapasitesi, yatak odası sayısı, konum ve havuz özellikleri bakımından daha çok alternatif bulabilirsiniz.</p><h2>Bütçe planlaması</h2><p>Tatil bütçenizi önceden belirleyebilir, ulaşım ve diğer harcamalarınızı zamana yayabilirsiniz. Fiyatın yanında temizlik ve hizmet ücretlerini de karşılaştırın.</p><h2>Koşulları okuyun</h2><p>Erken rezervasyonun iptal ve değişiklik şartları farklı olabilir. Ödeme takvimini ve iade koşullarını rezervasyon öncesinde mutlaka inceleyin.</p>','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=85','Akdeniz kıyısında yaz tatili manzarası','published',DATE_SUB(NOW(),INTERVAL 13 DAY),'Erken Rezervasyon Villa Tatili: Avantajlar ve İpuçları','Villa tatilinde erken rezervasyonun seçenek, bütçe ve planlama avantajlarını öğrenin.','erken rezervasyon villa tatili','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='erken-rezervasyon-villa-tatili');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Antalya’da Çocuk Dostu Villa Seçimi','antalyada-cocuk-dostu-villa-secimi','Çocuklu aileler için havuz güvenliği, oda düzeni ve konum konusunda kontrol edilmesi gerekenler.','<p>Çocuklarla villa tatili planlarken yetişkinlerin konforu kadar güvenlik ve günlük rutinler de önemlidir. Antalya’nın farklı bölgelerinde ailelere uygun seçenekler bulunabilir.</p><h2>Havuz güvenliğini sorun</h2><p>Havuz çevresinde kaymaz zemin, koruma kapısı veya güvenlik önlemleri bulunup bulunmadığını öğrenin. Küçük çocuklar havuz çevresinde her zaman yetişkin gözetiminde olmalıdır.</p><h2>Oda ve mutfak düzeni</h2><p>Çocuk yatağı, mama sandalyesi, çamaşır makinesi ve mutfak ekipmanları gibi ihtiyaçları önceden teyit edin.</p><h2>Çevre olanakları</h2><p>Market, sağlık merkezi, plaj ve restoran mesafelerini kontrol edin. Uzun araç yolculuklarını azaltacak bir konum seçmek rahatlık sağlar.</p>','https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85','Aile konaklamasına uygun bahçeli villa','published',DATE_SUB(NOW(),INTERVAL 15 DAY),'Antalya Çocuk Dostu Villa Rehberi | Aile Tatili','Antalya’da çocuklu aileler için havuz güvenliği, oda düzeni ve konum seçimi.','Antalya çocuk dostu villa','VillaStay Editör','5',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='antalyada-cocuk-dostu-villa-secimi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Dalyan’da Doğa ve Nehir Manzaralı Bir Tatil','dalyanda-doga-ve-nehir-tatili','Dalyan’ın sazlıkları, tekne rotaları ve sakin atmosferiyle farklı bir tatil planlayın.','<p>Dalyan, deniz tatilini doğa ve kültürle birleştirmek isteyenler için özel bir rota. Nehir kıyısı, sazlıklar ve çevredeki doğal alanlar bölgenin karakterini oluşturur.</p><h2>Nehir turu</h2><p>Dalyan kanalında tekne turu yaparak çevredeki doğal güzellikleri keşfedebilirsiniz. Tur saatlerini ve durakları önceden öğrenin.</p><h2>İztuzu Plajı</h2><p>Doğal koruma alanı olan plajda yerel kurallara uyun ve çevreyi temiz tutun. Ziyaret saatleri ve ulaşım seçeneklerini kontrol edin.</p><h2>Sakin konaklama</h2><p>Merkeze yakın veya doğa içinde villa seçeneklerini karşılaştırın. Bisiklet, yürüyüş ve restoran mesafeleri tatilinizi şekillendirebilir.</p>','https://images.unsplash.com/photo-1473116763249-2faaef81ccda?auto=format&fit=crop&w=1200&q=85','Nehir ve doğa manzarası','published',DATE_SUB(NOW(),INTERVAL 17 DAY),'Dalyan Tatil Rehberi: Nehir, Doğa ve İztuzu','Dalyan’da tekne turu, İztuzu Plajı ve doğa içinde konaklama önerileri.','Dalyan tatil rehberi','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='dalyanda-doga-ve-nehir-tatili');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Villa Kiralarken İlan Açıklamasında Nelere Bakılmalı?','villa-kiralarken-ilan-aciklamasi','Rezervasyon öncesinde ilan detaylarını doğru okumak için kapsamlı bir kontrol listesi.','<p>Bir villayı yalnızca fotoğraflarına bakarak seçmek yanıltıcı olabilir. İlan açıklamasında yer alan bilgiler, konaklamanızın beklentilerinize uygun olup olmadığını anlamanıza yardımcı olur.</p><h2>Kapasite ve yatak düzeni</h2><p>Maksimum misafir sayısının yanı sıra yatak odası, yatak ve banyo sayısını kontrol edin. Çekyat gibi ek yatakların nasıl düzenlendiğini sorun.</p><h2>Konum ve ulaşım</h2><p>Adresin yaklaşık konumunu, plaj ve market mesafesini, yol koşullarını ve otopark durumunu inceleyin.</p><h2>Ücretler ve kurallar</h2><p>Temizlik, depozito, elektrik veya ısıtma gibi ek ücretleri sorun. Evcil hayvan, sigara ve etkinlik kurallarını okuyun.</p><h2>Fotoğraflar ve iletişim</h2><p>Fotoğrafların tüm odaları ve dış alanları gösterdiğinden emin olun. Belirsiz noktaları rezervasyondan önce yazılı olarak teyit edin.</p>','https://images.unsplash.com/photo-1600566753086-00f18fb6b3ea?auto=format&fit=crop&w=1200&q=85','Modern villa iç mekânı ve salon','published',DATE_SUB(NOW(),INTERVAL 19 DAY),'Villa Kiralarken İlan Açıklaması Nasıl Okunur?','Villa rezervasyonu öncesi kapasite, konum, ek ücretler, ev kuralları ve fotoğrafları kontrol edin.','villa kiralarken dikkat edilmesi gerekenler','VillaStay Editör','5',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='villa-kiralarken-ilan-aciklamasi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Akdeniz’de Gün Batımını İzleyebileceğiniz Tatil Rotaları','akdenizde-gun-batimi-rotalari','Kaş, Kalkan ve Fethiye çevresinde gün batımı manzarasıyla öne çıkan tatil fikirleri.','<p>Akdeniz’de gün batımı, tatilin en unutulmaz anlarından biri olabilir. Doğru noktayı seçmek için mevsim, manzara yönü ve ulaşım koşullarını birlikte düşünün.</p><h2>Kaş’ın seyir noktaları</h2><p>Kaş merkez ve çevresindeki teraslar, denize karşı akşam saatlerini değerlendirmek için güzel seçenekler sunar.</p><h2>Kalkan terasları</h2><p>Yüksek konumdaki villalar ve restoranlar geniş deniz manzaraları sağlayabilir. Rezervasyon yaparken manzaranın hangi yönde olduğunu sorun.</p><h2>Fethiye kıyıları</h2><p>Sahil yürüyüşü veya tekne turu sonrası gün batımını izlemek için hava durumunu ve dönüş ulaşımını planlayın.</p><p>Gün batımının saati mevsime göre değiştiğinden programınızı seyahatinizin tarihine göre ayarlayın.</p>','https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?auto=format&fit=crop&w=1200&q=85','Akdeniz üzerinde gün batımı','published',DATE_SUB(NOW(),INTERVAL 21 DAY),'Akdeniz Gün Batımı Rotaları: Kaş, Kalkan ve Fethiye','Akdeniz tatilinde gün batımı manzaraları için Kaş, Kalkan ve Fethiye rota önerileri.','Akdeniz gün batımı','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='akdenizde-gun-batimi-rotalari');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Villa Tatilinde Mutfak Kullanımı ve Yerel Alışveriş Önerileri','villa-tatilinde-mutfak-ve-yerel-alisveris','Kendi mutfağınızın rahatlığını yerel pazar ve lezzet keşifleriyle birleştirin.','<p>Villada konaklamanın güzel yanlarından biri, günün bazı öğünlerini kendi ritminize göre hazırlayabilmenizdir. Yerel pazarlar ve küçük üreticiler tatilinize lezzet katar.</p><h2>Alışverişi planlayın</h2><p>Varış gününüzde temel ihtiyaçları alın. Sebze, meyve, su ve kahvaltılık ürünler için yakın marketleri veya semt pazarlarını araştırın.</p><h2>Yerel ürünleri deneyin</h2><p>Bölgeye özgü zeytinyağı, peynir, bal ve mevsim meyvelerini keşfedin. Ürünlerin saklama koşullarına dikkat edin.</p><h2>Mutfak ekipmanlarını sorun</h2><p>Kahve makinesi, fırın, barbekü veya çocuk ekipmanları gibi ihtiyaçlarınız varsa ilanda bulunup bulunmadığını önceden teyit edin.</p>','https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=1200&q=85','Taze yerel ürünlerle hazırlanmış sofra','published',DATE_SUB(NOW(),INTERVAL 23 DAY),'Villa Tatilinde Mutfak ve Yerel Alışveriş Rehberi','Villa mutfağını kullanırken yerel pazarlar, temel alışveriş ve mutfak ekipmanları önerileri.','villa tatili mutfak','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='villa-tatilinde-mutfak-ve-yerel-alisveris');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Tekne Turu mu, Koy Keşfi mi? Tatil Gününüzü Nasıl Planlamalısınız?','tekne-turu-mu-koy-kesfi-mi','Deniz tatilinizde tekne turu ve karadan koy keşfi seçeneklerini karşılaştırın.','<p>Akdeniz kıyılarında denizi keşfetmenin iki keyifli yolu tekne turuna katılmak veya kendi aracınızla farklı koyları gezmektir. Seçiminiz tatil sürenize ve beklentinize bağlıdır.</p><h2>Tekne turu</h2><p>Bir günde birden fazla koy görmek, araç kullanmadan denize ulaşmak ve rehberli rota izlemek isteyenler için uygundur. Tur süresi, yemek ve içecek dahil olup olmadığını kontrol edin.</p><h2>Kendi rotanız</h2><p>Karadan koy keşfi daha esnek saatler sunabilir. Otopark, yol koşulları, giriş ücretleri ve plaj imkânlarını önceden araştırın.</p><h2>Hava ve deniz koşulları</h2><p>Rüzgâr ve dalga durumu deniz planını etkileyebilir. Resmi uyarıları ve tur sağlayıcısının bilgilendirmelerini takip edin.</p>','https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1200&q=85','Turkuaz koyda tekne ve deniz','published',DATE_SUB(NOW(),INTERVAL 25 DAY),'Tekne Turu mu Koy Keşfi mi? Akdeniz Tatil Planı','Akdeniz’de tekne turu ve karadan koy gezisini süre, esneklik ve maliyet açısından karşılaştırın.','Akdeniz tekne turu','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='tekne-turu-mu-koy-kesfi-mi');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Tatil Bütçesi Hazırlarken Gözden Kaçan 6 Masraf','villa-tatili-butcesi-ek-masraflar','Konaklama fiyatı dışında ulaşım, temizlik ve günlük harcamaları da hesaba katın.','<p>Tatil bütçesi oluştururken yalnızca gecelik konaklama ücretine odaklanmak toplam maliyeti olduğundan düşük gösterebilir. Daha gerçekçi bir plan için tüm harcamaları birlikte hesaplayın.</p><h2>Ulaşım ve yakıt</h2><p>Havalimanı transferi, araç kiralama, yakıt ve otopark giderlerini ekleyin.</p><h2>Temizlik ve depozito</h2><p>İlanda belirtilen temizlik, hasar depozitosu veya ek hizmet ücretlerini kontrol edin.</p><h2>Market ve yemek</h2><p>Villada yemek hazırlayacak olsanız bile market alışverişi ve dışarıda yemek için pay ayırın.</p><h2>Aktiviteler</h2><p>Tekne turu, müze, plaj işletmesi ve ekipman kiralama gibi etkinliklerin maliyetlerini araştırın.</p><h2>Beklenmeyen giderler</h2><p>Toplam bütçenizde küçük bir esneklik payı bırakın ve ödeme koşullarını önceden okuyun.</p>','https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=1200&q=85','Tatil bütçesi ve planlama notları','published',DATE_SUB(NOW(),INTERVAL 27 DAY),'Villa Tatili Bütçesi: 6 Ek Masraf Kalemi','Villa tatili bütçesi hazırlarken ulaşım, temizlik, depozito, market ve aktivite masraflarını hesaplayın.','villa tatili bütçesi','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='villa-tatili-butcesi-ek-masraflar');

INSERT INTO blog_posts(title,slug,excerpt,content,featured_image,featured_image_alt,status,published_at,meta_title,meta_description,focus_keyword,author_name,reading_time,is_featured)
SELECT 'Kışın da Villa Tatili: Isıtmalı Havuz ve Konfor Kontrolü','kisin-villa-tatili-isitmali-havuz','Sezon dışında villa kiralarken ısıtma, havuz ve çevre koşullarını mutlaka teyit edin.','<p>Villa tatili yalnızca yaz aylarına özgü değildir. Uygun donanımlı bir konaklama, daha sakin dönemlerde de keyifli bir kaçamak sunabilir.</p><h2>Isıtma sistemini öğrenin</h2><p>Salon ve yatak odalarında hangi ısıtma sisteminin bulunduğunu, kullanım ücretlerini ve sıcak su kapasitesini sorun.</p><h2>Havuz ısıtması</h2><p>Isıtmalı havuzun gerçekten sunulup sunulmadığını, sıcaklık aralığını, ek ücretini ve önceden çalıştırma süresini teyit edin.</p><h2>Mevsim koşulları</h2><p>Yağış, rüzgâr, yol durumu ve yakın çevrede açık olan işletmeleri araştırın. Dış alanların kış kullanımına uygunluğunu kontrol edin.</p><p>Sezon dışında rezervasyon yaparken tüm hizmetleri yazılı olarak doğrulamak önemlidir.</p>','https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=85','Serin mevsimde sıcak havuzlu villa','published',DATE_SUB(NOW(),INTERVAL 29 DAY),'Kışın Villa Tatili: Isıtmalı Havuz ve Isınma Rehberi','Kış aylarında villa kiralarken havuz ısıtması, iç mekân ısınması ve mevsim koşullarını kontrol edin.','kışın villa tatili','VillaStay Editör','4',0
WHERE NOT EXISTS(SELECT 1 FROM blog_posts WHERE slug='kisin-villa-tatili-isitmali-havuz');

INSERT INTO blog_post_category(post_id,category_id)
SELECT p.id,c.id FROM blog_posts p JOIN blog_categories c ON c.slug=CASE
 WHEN p.slug IN ('kasta-villa-tatili-rehberi','kalkanda-deniz-manzarali-villa-secimi','ozel-havuzlu-villa-mi-tatil-koyu-mu','villa-kiralarken-ilan-aciklamasi','villa-tatili-butcesi-ek-masraflar','kisin-villa-tatili-isitmali-havuz') THEN 'villa-tatili'
 WHEN p.slug IN ('fethiyede-ailece-yapilacak-aktiviteler','dalyanda-doga-ve-nehir-tatili','akdenizde-gun-batimi-rotalari') THEN 'destinasyon-rehberi'
 WHEN p.slug IN ('villa-tatilinde-bavul-listesi','erken-rezervasyon-villa-tatili','tekne-turu-mu-koy-kesfi-mi') THEN 'seyahat-ipuclari'
 WHEN p.slug='antalyada-cocuk-dostu-villa-secimi' THEN 'aile-tatili'
 WHEN p.slug='balayi-icin-romantik-villa-secimi' THEN 'balayi'
 WHEN p.slug='villa-tatilinde-mutfak-ve-yerel-alisveris' THEN 'yeme-icme'
 ELSE 'villa-tatili' END
WHERE p.slug IN ('kasta-villa-tatili-rehberi','kalkanda-deniz-manzarali-villa-secimi','fethiyede-ailece-yapilacak-aktiviteler','ozel-havuzlu-villa-mi-tatil-koyu-mu','balayi-icin-romantik-villa-secimi','villa-tatilinde-bavul-listesi','erken-rezervasyon-villa-tatili','antalyada-cocuk-dostu-villa-secimi','dalyanda-doga-ve-nehir-tatili','villa-kiralarken-ilan-aciklamasi','akdenizde-gun-batimi-rotalari','villa-tatilinde-mutfak-ve-yerel-alisveris','tekne-turu-mu-koy-kesfi-mi','villa-tatili-butcesi-ek-masraflar','kisin-villa-tatili-isitmali-havuz')
AND NOT EXISTS(SELECT 1 FROM blog_post_category pc WHERE pc.post_id=p.id AND pc.category_id=c.id);

INSERT INTO blog_post_tag(post_id,tag_id)
SELECT p.id,t.id FROM blog_posts p JOIN blog_tags t ON t.slug=CASE
 WHEN p.slug LIKE '%kas%' THEN 'kas'
 WHEN p.slug LIKE '%kalkan%' THEN 'kalkan'
 WHEN p.slug LIKE '%fethiye%' THEN 'fethiye'
 WHEN p.slug LIKE '%antalya%' THEN 'antalya'
 WHEN p.slug LIKE '%balayi%' THEN 'balayi'
 WHEN p.slug LIKE '%tekne%' THEN 'tekne-turu'
 WHEN p.slug LIKE '%erken-rezervasyon%' THEN 'erken-rezervasyon'
 ELSE 'villa-secimi' END
WHERE p.slug IN ('kasta-villa-tatili-rehberi','kalkanda-deniz-manzarali-villa-secimi','fethiyede-ailece-yapilacak-aktiviteler','ozel-havuzlu-villa-mi-tatil-koyu-mu','balayi-icin-romantik-villa-secimi','villa-tatilinde-bavul-listesi','erken-rezervasyon-villa-tatili','antalyada-cocuk-dostu-villa-secimi','dalyanda-doga-ve-nehir-tatili','villa-kiralarken-ilan-aciklamasi','akdenizde-gun-batimi-rotalari','villa-tatilinde-mutfak-ve-yerel-alisveris','tekne-turu-mu-koy-kesfi-mi','villa-tatili-butcesi-ek-masraflar','kisin-villa-tatili-isitmali-havuz')
AND NOT EXISTS(SELECT 1 FROM blog_post_tag pt WHERE pt.post_id=p.id AND pt.tag_id=t.id);
